<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EngineerLaunch — Jobs & Interview Prep</title>
<style>
:root{--ink:#10213e;--blue:#2563eb;--muted:#667085;--line:#e4e9f2;--bg:#f6f8fc}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font-family:Inter,system-ui,sans-serif}a{text-decoration:none;color:inherit}button,input,select{font:inherit}.wrap{width:min(1160px,calc(100% - 32px));margin:auto}header{color:#fff;background:radial-gradient(circle at 85% 15%,#1d4ed8,transparent 32%),#0b1933}nav{height:70px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:21px;font-weight:850}.brand b{color:#60a5fa}nav div{display:flex;gap:24px;color:#cbd5e1;font-size:14px}.hero{padding:55px 0 70px}.eyebrow{color:#93c5fd;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}h1{max-width:800px;margin:12px 0;font-size:clamp(39px,6vw,65px);line-height:1.03;letter-spacing:-2px}.hero p{max-width:680px;color:#cbd5e1;font-size:18px;line-height:1.6}.search{display:grid;grid-template-columns:1.5fr 1fr auto;gap:9px;max-width:900px;margin-top:26px;padding:9px;background:#fff;border-radius:13px}.search input,.search select{min-width:0;padding:14px;border:1px solid var(--line);border-radius:8px;color:var(--ink);background:#fff}.btn{border:0;border-radius:8px;padding:13px 22px;background:var(--blue);color:#fff;font-weight:750;cursor:pointer}.stats{display:flex;flex-wrap:wrap;gap:30px;margin-top:30px;color:#cbd5e1}.stats strong{display:block;color:#fff;font-size:23px}section{padding:58px 0}.head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:23px}h2{margin:0 0 6px;font-size:30px}.sub{margin:0;color:var(--muted)}.companies{display:flex;gap:9px;overflow:auto;padding-bottom:10px}.company-pill,.chip{flex:none;border:1px solid var(--line);border-radius:999px;padding:9px 14px;background:#fff;color:var(--ink);cursor:pointer}.filters{display:flex;gap:7px;flex-wrap:wrap}.chip.active{border-color:var(--ink);background:var(--ink);color:#fff}.jobs,.tracks{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{padding:21px;border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:0 8px 25px #10213e0a}.job{display:flex;min-height:238px;flex-direction:column}.company{color:var(--blue);font-size:12px;font-weight:850;text-transform:uppercase}.job h3,.track h3{margin:10px 0;font-size:19px}.meta{color:var(--muted);font-size:14px;line-height:1.6}.tags{display:flex;flex-wrap:wrap;gap:6px;margin:14px 0}.tag{padding:5px 8px;border-radius:6px;background:#eff6ff;color:#1d4ed8;font-size:12px}.apply{margin-top:auto;color:var(--blue);font-size:14px;font-weight:750}.prep{background:#eaf1ff}.icon{width:42px;height:42px;display:grid;place-items:center;border-radius:10px;background:var(--blue);color:#fff;font-weight:850}.topics{padding-left:18px;color:var(--muted);font-size:14px;line-height:1.8}.notice,.empty{padding:18px;border-radius:8px;background:#fff7ed;color:#7c2d12}.notice{margin-top:22px;border-left:4px solid #f97316}.empty{grid-column:1/-1;text-align:center}footer{padding:30px 0;background:#0b1933;color:#94a3b8;font-size:14px}@media(max-width:850px){.jobs,.tracks{grid-template-columns:1fr 1fr}.search{grid-template-columns:1fr}}@media(max-width:560px){nav div{display:none}.jobs,.tracks{grid-template-columns:1fr}.head{align-items:start;flex-direction:column}}
.advanced{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;max-width:900px;margin-top:10px}.advanced select{min-width:0;padding:13px;border:1px solid var(--line);border-radius:8px;color:var(--ink);background:#fff}.dsa-toolbar{display:flex;gap:10px;margin-bottom:18px}.dsa-toolbar input{width:100%;padding:13px;border:1px solid var(--line);border-radius:9px}.dsa-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.dsa-card summary{cursor:pointer;font-size:17px;font-weight:800;list-style:none}.dsa-card summary::after{content:'+';float:right;color:var(--blue)}.dsa-card[open] summary::after{content:'−'}.question-list{display:grid;gap:7px;margin-top:14px}.question{padding:9px 10px;border-radius:7px;background:#f8fafc;color:#475467;font-size:13px}.count{color:var(--muted);font-size:12px;font-weight:500}@media(max-width:850px){.advanced,.dsa-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.advanced,.dsa-grid{grid-template-columns:1fr}}
.advanced{max-width:1160px}.advanced select,.advanced input{min-width:0;padding:13px;border:1px solid var(--line);border-radius:8px;color:var(--ink);background:#fff}.filter-note{max-width:1160px;margin:9px 0 0;color:#94a3b8;font-size:12px}.source-badge{display:inline-flex;margin-top:8px;padding:4px 7px;border-radius:5px;background:#ecfdf3;color:#067647;font-size:11px;font-weight:700}
/* Coordinated navigation and interaction polish */
header nav.wrap{width:calc(100% - 64px);max-width:none}
nav>div{margin-left:auto;justify-content:flex-end}
.card{transition:transform .22s ease,border-color .22s ease,box-shadow .22s ease}
.card:hover,.card:focus-within{transform:translateY(-5px);border-color:var(--blue);box-shadow:0 18px 38px rgba(37,99,235,.14)}
a.card{display:block;cursor:pointer}
.company-pill:hover,.company-pill:focus,.chip:hover,.chip:focus{border-color:var(--blue);box-shadow:0 5px 14px rgba(37,99,235,.13)}
@media(max-width:850px){header nav.wrap{width:calc(100% - 32px)}}
</style></head><body>
<header><nav class="wrap"><a class="brand" href="/">Engineer<b>Launch</b></a><div><a href="#jobs">Latest jobs</a><a href="#companies">Companies</a><a href="#dsa">DSA sheet</a><a href="#prepare">Interview prep</a></div></nav><div class="hero"><div class="wrap"><div class="eyebrow">Official career destinations, one discovery portal</div><h1>Find the engineering role worth preparing for.</h1><p>Explore opportunities by company, location and technology, then follow a focused preparation track before your interview.</p><form id="search"><div class="search"><input id="keyword" placeholder="Role, skill or company — Java, SDE, IBM" aria-label="Keyword"><select id="country" aria-label="Region"><option value="">All regions</option></select><button class="btn">Search jobs</button></div><div class="advanced"><input id="location" list="popular-cities" placeholder="City — Mohali, Pune, Noida"><datalist id="popular-cities"><option value="Mohali"><option value="Chandigarh"><option value="Zirakpur"><option value="Pune"><option value="Delhi"><option value="Gurugram"><option value="Noida"><option value="Faridabad"><option value="Mumbai"><option value="Bengaluru"><option value="Hyderabad"></datalist><select id="posted-days"><option value="">Any posting date</option><option value="7">Last 7 days</option><option value="15">Last 15 days</option><option value="25">Last 25 days</option><option value="35">Last 35 days</option></select><select id="posting-source"><option value="">Any listing source</option><option value="official_company">Direct company opening</option><option value="recruitment_agency">Recruitment agency</option><option value="job_board">External job board</option></select><select id="work-mode"><option value="">Any work arrangement</option><option value="office">On-site</option><option value="hybrid">Hybrid</option><option value="remote">Remote</option><option value="temporary_remote">Temporary remote</option></select><select id="experience-years"><option value="">Any experience</option><option value="0">Fresher</option><option value="1">1 year</option><option value="3">3 years</option><option value="5">5 years</option><option value="7">7 years</option><option value="10">10 years</option></select><select id="role-family"><option value="">Any role family</option><option value="software-development">Software development</option><option value="frontend">Frontend engineering</option><option value="backend">Backend engineering</option><option value="full-stack">Full-stack engineering</option><option value="quality-testing">Quality engineering & testing</option><option value="devops-cloud">DevOps, cloud & platform</option><option value="data-ai">Data & AI</option><option value="security">Cybersecurity</option></select><select id="salary-min"><option value="">Any minimum salary</option><option value="300000">₹3 lakh+</option><option value="600000">₹6 lakh+</option><option value="1000000">₹10 lakh+</option><option value="1500000">₹15 lakh+</option><option value="2500000">₹25 lakh+</option><option value="5000000">₹50 lakh+</option></select><select id="technology"><option value="">All tech stacks</option></select><select id="category"><option value="">All role categories</option></select><select id="job-type"><option value="">All job types</option><option>Full-time</option><option>Part-time</option><option>Contract</option><option>Internship</option></select></div><p class="filter-note">Counts are calculated from EngineerLaunch data. Third-party portal counts are not copied.</p></form><div class="stats"><div><strong id="job-count">—</strong>active jobs</div><div><strong id="company-count">—</strong>companies tracked</div><div><strong id="tech-count">—</strong>technologies</div></div></div></div></header>
<main><section id="companies"><div class="wrap"><div class="head"><div><h2>Companies we track</h2><p class="sub">Select a company to see its openings.</p></div></div><div class="companies" id="company-list"><span class="company-pill">Loading companies…</span></div></div></section>
<section id="jobs"><div class="wrap"><div class="head"><div><h2>Latest engineering jobs</h2><p class="sub" id="result">Fresh roles stored from career sources.</p></div><div class="filters"><button class="chip active" data-sort="posted_at">Newest</button><button class="chip" data-sort="views">Popular</button><button class="chip" data-q="graduate">Graduate</button><button class="chip" data-q="remote">Remote</button></div></div><div class="jobs" id="job-list"><div class="empty">Loading opportunities…</div></div></div></section>
<section id="dsa"><div class="wrap"><div class="head"><div><h2>Data Structures & Algorithms sheet</h2><p class="sub">A structured interview roadmap based on your curriculum, from arrays to advanced range queries.</p></div></div><div class="dsa-toolbar"><input id="dsa-search" type="search" placeholder="Search questions — stack using queue, Dijkstra, LRU cache…" aria-label="Search DSA questions"></div><div class="dsa-grid" id="dsa-grid">@foreach($dsaTracks as $topic => $questions)<details class="card dsa-card" data-topic="{{ strtolower($topic.' '.implode(' ', $questions)) }}"><summary>{{ $topic }} <span class="count">{{ count($questions) }} questions</span></summary><div class="question-list">@foreach($questions as $question)<div class="question">{{ $question }}</div>@endforeach</div></details>@endforeach</div></div></section>
<section class="prep" id="prepare"><div class="wrap"><div class="head"><div><h2>Prepare for the role you want</h2><p class="sub">Fundamentals, frameworks and real system-design scenarios.</p></div></div><div class="tracks">
<article class="card track"><div class="icon">J</div><h3>Java & Spring Boot</h3><p class="sub">Backend developer</p><ul class="topics"><li>Java, OOP, abstraction, exceptions</li><li>Collections and multithreading</li><li>Spring Boot, REST, dependency injection</li><li>Microservice resilience and failures</li><li>Low- and high-level system design</li></ul><a class="btn" href="/learn" style="display:block;text-align:center;margin-top:16px">Start Java preparation →</a></article>
<article class="card track"><div class="icon" style="background:#7c3aed">PHP</div><h3>PHP & Laravel</h3><p class="sub">Web application developer</p><ul class="topics"><li>Modern PHP, OOP and SOLID</li><li>Service container and providers</li><li>Jobs, queues, batches, failed jobs</li><li>Scheduler, workers and cron</li><li>Database, caching and API security</li></ul><a class="btn" href="/learn/laravel/request-lifecycle" style="display:block;text-align:center;margin-top:16px">Start Laravel preparation →</a></article>
<article class="card track"><div class="icon" style="background:#0891b2">JS</div><h3>Frontend Engineering</h3><p class="sub">UI developer</p><ul class="topics"><li>Semantic HTML, CSS, accessibility</li><li>JavaScript, TypeScript, event loop</li><li>React, hooks and state management</li><li>Testing, performance and security</li><li>Frontend architecture and APIs</li></ul><a class="btn" href="/practice" style="display:block;text-align:center;margin-top:16px">Open live practice editor →</a></article></div><div class="notice"><b>Personalization path:</b> a job’s existing technology tags provide the starting checklist. Full saved learning plans can be added when user applications and profiles are introduced.</div></div></section></main>
<footer><div class="wrap">EngineerLaunch helps users discover roles and redirects applications to official sources. · <a href="/about" style="color:#60a5fa">About us</a> · <a href="/learn" style="color:#60a5fa">Learning center</a> · <a href="/practice" style="color:#60a5fa">Practice editor</a> · <a href="/login" style="color:#60a5fa">Login</a> · <a href="/register" style="color:#60a5fa">Sign up</a></div></footer>
<script>
const state={company:'',sort:'posted_at',q:''},esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));async function api(url){const r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw Error();return r.json()}function card(j){const tags=[...(j.categories||[]).map(x=>x.name),...(j.technologies||[]).map(x=>x.name)].slice(0,5),url=j.external_url||j.company?.careers_url||'#',date=j.posted_at?new Date(j.posted_at).toLocaleDateString():'Date unavailable';return `<article class="card job"><div class="company">${esc(j.company?.name||'Company')}</div><h3>${esc(j.title)}</h3><div class="meta">${esc(j.location||'Location not specified')} · ${esc(j.job_type||'Full-time')}<br>Posted ${esc(date)}</div><div class="tags">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><a class="apply" href="${esc(url)}" target="_blank" rel="noopener noreferrer">View on official careers site →</a></article>`}async function loadJobs(){const el=document.querySelector('#job-list');el.innerHTML='<div class="empty">Loading opportunities…</div>';const p=new URLSearchParams({per_page:18,sort_by:state.sort,sort_order:'desc'}),q=document.querySelector('#keyword').value.trim()||state.q,c=document.querySelector('#country').value;if(q)p.set('q',q);if(c)p.set('country',c);if(state.company)p.set('company_id',state.company);try{const x=await api('/api/jobs?'+p);el.innerHTML=x.data.length?x.data.map(card).join(''):'<div class="empty">No matching jobs are stored yet. Try a broader search while career feeds are populated.</div>';document.querySelector('#result').textContent=`${x.pagination.total} matching role${x.pagination.total===1?'':'s'}`}catch{el.innerHTML='<div class="empty">Could not load jobs. Confirm the database is migrated and connected.</div>'}}async function init(){try{const[s,co,cu]=await Promise.all([api('/api/jobs/stats'),api('/api/companies?per_page=100'),api('/api/companies/countries')]);document.querySelector('#job-count').textContent=s.data.total_jobs.toLocaleString();document.querySelector('#company-count').textContent=s.data.total_companies.toLocaleString();document.querySelector('#tech-count').textContent=s.data.total_technologies.toLocaleString();document.querySelector('#country').insertAdjacentHTML('beforeend',cu.data.filter(Boolean).map(x=>`<option>${esc(x)}</option>`).join(''));document.querySelector('#company-list').innerHTML=`<button class="company-pill" data-company="">All companies</button>`+co.data.map(x=>`<button class="company-pill" data-company="${x.id}">${esc(x.name)} (${x.active_jobs_count})</button>`).join('');document.querySelector('#company-list').onclick=e=>{const b=e.target.closest('[data-company]');if(!b)return;state.company=b.dataset.company;loadJobs();document.querySelector('#jobs').scrollIntoView({behavior:'smooth'})}}catch{document.querySelector('#company-list').innerHTML='<span class="company-pill">Company data unavailable</span>'}loadJobs()}document.querySelector('#search').onsubmit=e=>{e.preventDefault();state.company='';state.q='';loadJobs();document.querySelector('#jobs').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.sort=b.dataset.sort||'posted_at';state.q=b.dataset.q||'';document.querySelector('#keyword').value='';loadJobs()});init();
const originalFetch = window.fetch.bind(window);
document.querySelector('nav div')?.insertAdjacentHTML('beforeend','<a href="/learn">Learning</a><a href="/practice">Practice</a><a href="/about">About us</a><a href="/login">Login</a><a href="/register" class="btn" style="padding:9px 14px">Sign up</a>');
document.querySelector('nav div a[href="/about"]')?.insertAdjacentHTML('afterend','<a href="/resume/builder">Resume Builder</a>');
document.querySelector('main')?.insertAdjacentHTML('afterbegin',`<section style="padding:28px 0;background:#fff"><div class="wrap"><div class="head"><div><h2>Build your complete career journey</h2><p class="sub">Everything recently added is available from the main page.</p></div></div><div class="tracks"><a class="card track" href="/about"><div class="icon">01</div><h3>About EngineerLaunch</h3><p class="sub">Our company, mission, platform logic and promise to students.</p><span class="apply">Read about us →</span></a><a class="card track" href="/learn"><div class="icon" style="background:#7c3aed">02</div><h3>Learning & interview preparation</h3><p class="sub">Java, Laravel, DSA, system design, machine learning and data science.</p><span class="apply">Start learning →</span></a><a class="card track" href="/practice"><div class="icon" style="background:#0891b2">03</div><h3>Live practice editor</h3><p class="sub">Test HTML, CSS and JavaScript safely in your browser.</p><span class="apply">Open editor →</span></a></div></div></section>`);
window.fetch = (resource, options) => {
    if (typeof resource === 'string' && resource.split('?')[0] === '/api/jobs') {
        const url = new URL(resource, window.location.origin);
        const filters = {
            technology_id: document.querySelector('#technology')?.value,
            category_id: document.querySelector('#category')?.value,
            job_type: document.querySelector('#job-type')?.value,
            location: document.querySelector('#location')?.value.trim(),
            posted_within_days: document.querySelector('#posted-days')?.value,
            posting_source: document.querySelector('#posting-source')?.value,
            work_mode: document.querySelector('#work-mode')?.value,
            experience_years: document.querySelector('#experience-years')?.value,
            role_family: document.querySelector('#role-family')?.value,
            salary_min: document.querySelector('#salary-min')?.value,
        };
        Object.entries(filters).forEach(([key, value]) => value ? url.searchParams.set(key, value) : url.searchParams.delete(key));
        resource = url.pathname + url.search;
    }
    return originalFetch(resource, options);
};
Promise.all([api('/api/technologies?per_page=100'), api('/api/technologies/categories')]).then(([technologies]) => {
    document.querySelector('#technology').insertAdjacentHTML('beforeend', technologies.data.map(item => `<option value="${item.id}">${esc(item.name)}</option>`).join(''));
}).catch(() => {});
fetch('/api/jobs/categories', {headers:{Accept:'application/json'}}).then(response => response.ok ? response.json() : Promise.reject()).then(payload => {
    document.querySelector('#category').insertAdjacentHTML('beforeend', payload.data.map(item => `<option value="${item.id}">${esc(item.name)}</option>`).join(''));
}).catch(() => {});
['technology','category','job-type','posted-days','posting-source','work-mode','experience-years','role-family','salary-min'].forEach(id => document.querySelector('#' + id).addEventListener('change', loadJobs));
document.querySelector('#location').addEventListener('change', loadJobs);
document.querySelector('#dsa-search').addEventListener('input', event => {
    const term = event.target.value.trim().toLowerCase();
    document.querySelectorAll('.dsa-card').forEach(card => {
        const match = !term || card.dataset.topic.includes(term);
        card.hidden = !match;
        if (term && match) card.open = true;
    });
});
</script></body></html>
